ruleBookInfo.init:
@js:
(function(){
  try{ if(book){ book.type=32; book.originType=32; } }catch(e){}
  var bu = String(baseUrl || (book&&book.bookUrl) || '');
  function gv(k){
    try{
      var m = bu.match(new RegExp('[?&]' + k + '=([^&]*)'));
      if (m && m[1]) return decodeURIComponent(m[1]);
    }catch(e){}
    return '';
  }
  var name = gv('nm') || gv('title');
  var author = gv('au') || gv('author');
  var cover = gv('cv') || gv('cover');
  var intro = gv('it');
  var __o = {
    name: name || '酷我听书',
    author: author,
    coverUrl: cover,
    intro: intro,
    kind: '',
    tocUrl: ''
  };
  return JSON.stringify(__o);
})()

ruleToc.chapterList:
@js:
(function(){
  var d = JSON.parse(result);
  var arr = d.chapters || [];
  var out = [];
  var seen = {};
  for (var i=0;i<arr.length;i++){
    var it = arr[i] || {};
    var id = String(it.id || '');
    if (!id || seen[id]) continue;
    seen[id] = 1;
    out.push({ name: it.title || '', url: id });
  }
  return out;
})()

ruleContent.content:
@js:
(function(){
  try{ if(book){ book.type=32; book.originType=32; } }catch(e){}
  var d = JSON.parse(result);
  var u = (d && d.url) || '';
  return u;
})()
